WITH base AS (SELECT id, channel, promo_code, starts_on, ends_on, DATE_TRUNC('WEEK', ends_on) AS ends_on_period, COALESCE(channel, 'UNKNOWN') AS channel_clean FROM promotions WHERE ends_on >= TO_DATE('2023-09-30') AND channel IS NOT NULL) SELECT id, channel, promo_code, starts_on, ends_on, ends_on_period, channel_clean, FIRST_VALUE(channel) IGNORE NULLS OVER (ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel, LAST_VALUE(channel) IGNORE NULLS OVER (PARTITION BY channel, promo_code ORDER BY ends_on, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_channel FROM base
